from __future__ import annotations

from dataclasses import dataclass
from typing import Any

from .errors import ValidationError


def _identifier(value: Any, field: str) -> str:
    if not isinstance(value, str) or not value or len(value) > 100:
        raise ValidationError(f"{field} must be a non-empty string of at most 100 characters")
    return value


def _input_path(value: Any) -> str:
    if not isinstance(value, str) or not value or any(not segment for segment in value.split(".")):
        raise ValidationError("path must be a non-empty dot-separated input path")
    return value


def _json_scalar(value: Any, field: str) -> Any:
    if isinstance(value, (dict, list)):
        raise ValidationError(f"{field} must be a JSON scalar")
    return value


@dataclass(frozen=True)
class RunIf:
    condition_id: str
    expected: bool

    @classmethod
    def parse(cls, raw: Any) -> "RunIf":
        if not isinstance(raw, dict) or set(raw) != {"condition_id", "expected"}:
            raise ValidationError("run_if must contain exactly condition_id and expected")
        condition_id = _identifier(raw["condition_id"], "condition id")
        if not isinstance(raw["expected"], bool):
            raise ValidationError("run_if expected must be a boolean")
        return cls(condition_id, raw["expected"])

    def as_dict(self) -> dict[str, Any]:
        return {"condition_id": self.condition_id, "expected": self.expected}


@dataclass(frozen=True)
class Node:
    id: str
    kind: str
    depends_on: tuple[str, ...]
    path: str | None = None
    equals: Any = None
    run_if: RunIf | None = None

    @classmethod
    def parse(cls, raw: Any) -> "Node":
        if not isinstance(raw, dict):
            raise ValidationError("each node must be an object")
        kind = raw.get("kind")
        if kind not in ("task", "condition"):
            raise ValidationError("node kind must be task or condition")
        base = {"id", "kind", "depends_on"}
        if not base <= set(raw):
            raise ValidationError("each node must contain id, kind, and depends_on")
        node_id = _identifier(raw["id"], "node id")
        dependencies = raw["depends_on"]
        if not isinstance(dependencies, list) or any(not isinstance(item, str) for item in dependencies):
            raise ValidationError("depends_on must be an array of node identifiers")
        if len(dependencies) != len(set(dependencies)):
            raise ValidationError("depends_on must not contain duplicates")
        depends_on = tuple(dependencies)
        if kind == "task":
            if not set(raw) - base <= {"run_if"}:
                raise ValidationError("task nodes may only contain id, kind, depends_on, and run_if")
            run_if = RunIf.parse(raw["run_if"]) if "run_if" in raw else None
            return cls(node_id, "task", depends_on, run_if=run_if)
        if set(raw) != base | {"path", "equals"}:
            raise ValidationError("condition nodes must contain exactly id, kind, depends_on, path, and equals")
        return cls(
            node_id,
            "condition",
            depends_on,
            path=_input_path(raw["path"]),
            equals=_json_scalar(raw["equals"], "equals"),
        )

    def as_dict(self) -> dict[str, Any]:
        document: dict[str, Any] = {"id": self.id, "kind": self.kind, "depends_on": list(self.depends_on)}
        if self.kind == "condition":
            document["path"] = self.path
            document["equals"] = self.equals
        elif self.run_if is not None:
            document["run_if"] = self.run_if.as_dict()
        return document


@dataclass(frozen=True)
class Workflow:
    id: str
    nodes: tuple[Node, ...]

    @classmethod
    def parse(cls, raw: Any) -> "Workflow":
        if not isinstance(raw, dict) or set(raw) != {"id", "nodes"}:
            raise ValidationError("workflow must contain exactly id and nodes")
        workflow_id = _identifier(raw["id"], "workflow id")
        if not isinstance(raw["nodes"], list) or not raw["nodes"]:
            raise ValidationError("nodes must be a non-empty array")
        nodes = tuple(Node.parse(node) for node in raw["nodes"])
        identifiers = {node.id for node in nodes}
        if len(identifiers) != len(nodes):
            raise ValidationError("node identifiers must be unique")
        for node in nodes:
            if node.id in node.depends_on:
                raise ValidationError(f"node {node.id} cannot depend on itself")
            missing = set(node.depends_on) - identifiers
            if missing:
                raise ValidationError(f"node {node.id} has unknown dependencies: {', '.join(sorted(missing))}")
        by_id = {node.id: node for node in nodes}
        for node in nodes:
            if node.run_if is None:
                continue
            target = by_id.get(node.run_if.condition_id)
            if target is None or target.kind != "condition":
                raise ValidationError(f"node {node.id} run_if must reference a condition node")
            if node.run_if.condition_id not in node.depends_on:
                raise ValidationError(f"node {node.id} must list condition {node.run_if.condition_id} in depends_on")
        _assert_acyclic(nodes)
        return cls(workflow_id, nodes)

    def as_dict(self) -> dict[str, Any]:
        return {"id": self.id, "nodes": [node.as_dict() for node in self.nodes]}


def _assert_acyclic(nodes: tuple[Node, ...]) -> None:
    graph = {node.id: node.depends_on for node in nodes}
    visiting: set[str] = set()
    visited: set[str] = set()

    def visit(node_id: str) -> None:
        if node_id in visiting:
            raise ValidationError("workflow contains a dependency cycle")
        if node_id in visited:
            return
        visiting.add(node_id)
        for dependency in graph[node_id]:
            visit(dependency)
        visiting.remove(node_id)
        visited.add(node_id)

    for node_id in graph:
        visit(node_id)

from __future__ import annotations

from typing import Any, Callable

from .errors import ConflictError, NotFoundError, ValidationError
from .model import Node, Workflow, _identifier
from .store import Store


def _json_type(value: Any) -> str:
    if value is None:
        return "null"
    if isinstance(value, bool):
        return "boolean"
    if isinstance(value, (int, float)):
        return "number"
    if isinstance(value, str):
        return "string"
    return "other"


def _evaluate_condition(node: Node, input_data: Any) -> bool:
    current = input_data
    for segment in node.path.split("."):
        if not isinstance(current, dict) or segment not in current:
            return False
        current = current[segment]
    return _json_type(current) == _json_type(node.equals) and current == node.equals


class ChronicleFlow:
    def __init__(self, database: str):
        self.store = Store(database)

    def _idempotent(self, key: str | None, operation: str, action: Callable[[], dict[str, Any]]) -> dict[str, Any]:
        if not key:
            raise ValidationError("Idempotency-Key header is required")
        with self.store.transaction() as connection:
            existing = connection.execute("SELECT operation, response FROM idempotency WHERE key = ?", (key,)).fetchone()
            if existing:
                if existing["operation"] != operation:
                    raise ConflictError("idempotency key was already used for another operation")
                return self.store.decode(existing["response"])
            response = action()
            connection.execute(
                "INSERT INTO idempotency(key, operation, response) VALUES (?, ?, ?)",
                (key, operation, self.store.encode(response)),
            )
            return response

    def create_workflow(self, raw: Any, key: str | None) -> dict[str, Any]:
        workflow = Workflow.parse(raw)

        def create() -> dict[str, Any]:
            try:
                self.store.connection.execute(
                    "INSERT INTO workflows(id, document) VALUES (?, ?)",
                    (workflow.id, self.store.encode(workflow.as_dict())),
                )
            except Exception as error:
                if "UNIQUE constraint" in str(error):
                    raise ConflictError(f"workflow {workflow.id} already exists") from error
                raise
            return workflow.as_dict()

        return self._idempotent(key, f"create-workflow:{workflow.id}", create)

    def create_execution(self, raw: Any, key: str | None) -> dict[str, Any]:
        if not isinstance(raw, dict) or set(raw) != {"id", "workflow_id", "input"}:
            raise ValidationError("execution must contain exactly id, workflow_id, and input")
        execution_id = _identifier(raw["id"], "execution id")
        workflow_id = _identifier(raw["workflow_id"], "workflow id")
        if not isinstance(raw["input"], dict):
            raise ValidationError("input must be an object")

        def create() -> dict[str, Any]:
            workflow_row = self.store.connection.execute("SELECT document FROM workflows WHERE id = ?", (workflow_id,)).fetchone()
            if not workflow_row:
                raise NotFoundError(f"workflow {workflow_id} was not found")
            state = {
                "id": execution_id,
                "workflow_id": workflow_id,
                "status": "running",
                "input": raw["input"],
                "completed_nodes": [],
                "skipped_nodes": [],
                "condition_results": {},
                "outputs": {},
            }
            try:
                self.store.connection.execute(
                    "INSERT INTO executions(id, workflow_id, state) VALUES (?, ?, ?)",
                    (execution_id, workflow_id, self.store.encode(state)),
                )
            except Exception as error:
                if "UNIQUE constraint" in str(error):
                    raise ConflictError(f"execution {execution_id} already exists") from error
                raise
            self._append(execution_id, "execution_started", {"workflow_id": workflow_id, "input": raw["input"]})
            return state

        return self._idempotent(key, f"create-execution:{execution_id}", create)

    def get_execution(self, execution_id: str) -> dict[str, Any]:
        row = self.store.connection.execute("SELECT state FROM executions WHERE id = ?", (execution_id,)).fetchone()
        if not row:
            raise NotFoundError(f"execution {execution_id} was not found")
        return self.store.decode(row["state"])

    def events(self, execution_id: str) -> list[dict[str, Any]]:
        self.get_execution(execution_id)
        rows = self.store.connection.execute(
            "SELECT sequence, type, payload, occurred_at FROM events WHERE execution_id = ? ORDER BY sequence",
            (execution_id,),
        ).fetchall()
        return [
            {"sequence": row["sequence"], "type": row["type"], "payload": self.store.decode(row["payload"]), "occurred_at": row["occurred_at"]}
            for row in rows
        ]

    def advance(self, execution_id: str, raw: Any, key: str | None) -> dict[str, Any]:
        if not isinstance(raw, dict) or set(raw) != {"output"} or not isinstance(raw["output"], dict):
            raise ValidationError("advance body must contain exactly an output object")

        def apply() -> dict[str, Any]:
            state = self.get_execution(execution_id)
            if state["status"] != "running":
                return state
            workflow_row = self.store.connection.execute("SELECT document FROM workflows WHERE id = ?", (state["workflow_id"],)).fetchone()
            workflow = Workflow.parse(self.store.decode(workflow_row["document"]))
            self._auto_process(execution_id, workflow, state)
            if state["status"] == "running":
                satisfied = set(state["completed_nodes"]) | set(state["skipped_nodes"])
                ready = sorted(
                    node.id
                    for node in workflow.nodes
                    if node.kind == "task" and node.id not in satisfied and set(node.depends_on) <= satisfied
                )
                if not ready:
                    raise ConflictError("execution has no ready node")
                node_id = ready[0]
                state["completed_nodes"].append(node_id)
                state["outputs"][node_id] = raw["output"]
                self._append(execution_id, "node_completed", {"node_id": node_id, "output": raw["output"]})
                if len(state["completed_nodes"]) + len(state["skipped_nodes"]) == len(workflow.nodes):
                    state["status"] = "completed"
                    self._append(execution_id, "execution_completed", {})
            self.store.connection.execute("UPDATE executions SET state = ? WHERE id = ?", (self.store.encode(state), execution_id))
            return state

        return self._idempotent(key, f"advance:{execution_id}", apply)

    def _auto_process(self, execution_id: str, workflow: Workflow, state: dict[str, Any]) -> None:
        completed = set(state["completed_nodes"])
        skipped = set(state["skipped_nodes"])
        changed = True
        while changed:
            changed = False
            for node in sorted(workflow.nodes, key=lambda item: item.id):
                if node.id in completed or node.id in skipped:
                    continue
                if not set(node.depends_on) <= completed | skipped:
                    continue
                if node.kind == "condition":
                    result = _evaluate_condition(node, state["input"])
                    state["condition_results"][node.id] = result
                    state["completed_nodes"].append(node.id)
                    completed.add(node.id)
                    self._append(execution_id, "condition_evaluated", {"node_id": node.id, "result": result})
                    changed = True
                elif node.run_if is not None and state["condition_results"][node.run_if.condition_id] != node.run_if.expected:
                    state["skipped_nodes"].append(node.id)
                    skipped.add(node.id)
                    self._append(execution_id, "node_skipped", {"node_id": node.id})
                    changed = True
        if len(completed) + len(skipped) == len(workflow.nodes):
            state["status"] = "completed"
            self._append(execution_id, "execution_completed", {})

    def replay(self, execution_id: str) -> dict[str, Any]:
        stored = self.get_execution(execution_id)
        rebuilt: dict[str, Any] | None = None
        for event in self.events(execution_id):
            if event["type"] == "execution_started":
                rebuilt = {
                    "id": execution_id,
                    "workflow_id": event["payload"]["workflow_id"],
                    "status": "running",
                    "input": event["payload"]["input"],
                    "completed_nodes": [],
                    "skipped_nodes": [],
                    "condition_results": {},
                    "outputs": {},
                }
            elif event["type"] == "condition_evaluated" and rebuilt is not None:
                node_id = event["payload"]["node_id"]
                rebuilt["condition_results"][node_id] = event["payload"]["result"]
                rebuilt["completed_nodes"].append(node_id)
            elif event["type"] == "node_skipped" and rebuilt is not None:
                rebuilt["skipped_nodes"].append(event["payload"]["node_id"])
            elif event["type"] == "node_completed" and rebuilt is not None:
                node_id = event["payload"]["node_id"]
                rebuilt["completed_nodes"].append(node_id)
                rebuilt["outputs"][node_id] = event["payload"]["output"]
            elif event["type"] == "execution_completed" and rebuilt is not None:
                rebuilt["status"] = "completed"
        if rebuilt is None:
            raise ConflictError("execution event stream has no start event")
        return {"consistent": rebuilt == stored, "execution": rebuilt}

    def _append(self, execution_id: str, event_type: str, payload: dict[str, Any]) -> None:
        row = self.store.connection.execute(
            "SELECT COALESCE(MAX(sequence), 0) + 1 AS sequence FROM events WHERE execution_id = ?",
            (execution_id,),
        ).fetchone()
        self.store.connection.execute(
            "INSERT INTO events(execution_id, sequence, type, payload, occurred_at) VALUES (?, ?, ?, ?, ?)",
            (execution_id, row["sequence"], event_type, self.store.encode(payload), self.store.now()),
        )

from __future__ import annotations

import json
import sqlite3
from contextlib import contextmanager
from datetime import datetime, timezone
from pathlib import Path
from typing import Any, Iterator


class Store:
    def __init__(self, path: str):
        Path(path).parent.mkdir(parents=True, exist_ok=True)
        self.connection = sqlite3.connect(path, isolation_level=None, check_same_thread=False)
        self.connection.row_factory = sqlite3.Row
        self.connection.execute("PRAGMA foreign_keys = ON")
        self.connection.execute("PRAGMA journal_mode = WAL")
        self.connection.executescript(
            """
            CREATE TABLE IF NOT EXISTS workflows (
              id TEXT PRIMARY KEY,
              document TEXT NOT NULL
            );
            CREATE TABLE IF NOT EXISTS executions (
              id TEXT PRIMARY KEY,
              workflow_id TEXT NOT NULL REFERENCES workflows(id),
              state TEXT NOT NULL
            );
            CREATE TABLE IF NOT EXISTS events (
              execution_id TEXT NOT NULL REFERENCES executions(id),
              sequence INTEGER NOT NULL,
              type TEXT NOT NULL,
              payload TEXT NOT NULL,
              occurred_at TEXT NOT NULL,
              PRIMARY KEY (execution_id, sequence)
            );
            CREATE TABLE IF NOT EXISTS idempotency (
              key TEXT PRIMARY KEY,
              operation TEXT NOT NULL,
              response TEXT NOT NULL
            );
            """
        )

    @contextmanager
    def transaction(self) -> Iterator[sqlite3.Connection]:
        self.connection.execute("BEGIN IMMEDIATE")
        try:
            yield self.connection
        except Exception:
            self.connection.execute("ROLLBACK")
            raise
        else:
            self.connection.execute("COMMIT")

    @staticmethod
    def encode(value: Any) -> str:
        return json.dumps(value, ensure_ascii=False, separators=(",", ":"), sort_keys=True)

    @staticmethod
    def decode(value: str) -> Any:
        return json.loads(value)

    @staticmethod
    def now() -> str:
        return datetime.now(timezone.utc).isoformat().replace("+00:00", "Z")

from __future__ import annotations

import argparse
import json
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from typing import Any
from urllib.parse import urlsplit

from .errors import ChronicleFlowError, NotFoundError, ValidationError
from .service import ChronicleFlow


class Handler(BaseHTTPRequestHandler):
    service: ChronicleFlow

    def log_message(self, format: str, *args: Any) -> None:
        return

    def _json(self, status: int, value: Any) -> None:
        body = json.dumps(value, ensure_ascii=False, separators=(",", ":")).encode()
        self.send_response(status)
        self.send_header("Content-Type", "application/json; charset=utf-8")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def _body(self) -> Any:
        content_type = self.headers.get("Content-Type", "")
        if content_type.split(";", 1)[0].strip().lower() != "application/json":
            raise ValidationError("Content-Type must be application/json")
        try:
            length = int(self.headers.get("Content-Length", "0"))
            if length < 0 or length > 1_000_000:
                raise ValueError
            return json.loads(self.rfile.read(length))
        except (ValueError, json.JSONDecodeError) as error:
            raise ValidationError("request body must be valid JSON") from error

    def _dispatch(self) -> tuple[int, Any]:
        path = urlsplit(self.path).path
        parts = [part for part in path.split("/") if part]
        if self.command == "GET" and parts == ["health"]:
            return 200, {"status": "ok"}
        if self.command == "POST" and parts == ["workflows"]:
            return 201, self.service.create_workflow(self._body(), self.headers.get("Idempotency-Key"))
        if self.command == "POST" and parts == ["executions"]:
            return 201, self.service.create_execution(self._body(), self.headers.get("Idempotency-Key"))
        if len(parts) == 2 and parts[0] == "executions" and self.command == "GET":
            return 200, self.service.get_execution(parts[1])
        if len(parts) == 3 and parts[0] == "executions" and parts[2] == "events" and self.command == "GET":
            return 200, {"events": self.service.events(parts[1])}
        if len(parts) == 3 and parts[0] == "executions" and parts[2] == "advance" and self.command == "POST":
            return 200, self.service.advance(parts[1], self._body(), self.headers.get("Idempotency-Key"))
        if len(parts) == 3 and parts[0] == "executions" and parts[2] == "replay" and self.command == "POST":
            return 200, self.service.replay(parts[1])
        raise NotFoundError("route was not found")

    def _handle(self) -> None:
        try:
            status, response = self._dispatch()
            self._json(status, response)
        except ChronicleFlowError as error:
            self._json(error.status, {"error": {"code": error.code, "message": str(error)}})
        except Exception:
            self._json(500, {"error": {"code": "internal_error", "message": "internal server error"}})

    do_GET = _handle
    do_POST = _handle


def main() -> None:
    parser = argparse.ArgumentParser(description="Run the ChronicleFlow HTTP service")
    parser.add_argument("--host", default="127.0.0.1")
    parser.add_argument("--port", default=8080, type=int)
    parser.add_argument("--database", default="chronicleflow.db")
    arguments = parser.parse_args()
    Handler.service = ChronicleFlow(arguments.database)
    server = ThreadingHTTPServer((arguments.host, arguments.port), Handler)
    print(f"ChronicleFlow listening on http://{arguments.host}:{arguments.port}", flush=True)
    server.serve_forever()


if __name__ == "__main__":
    main()

class ChronicleFlowError(Exception):
    code = "internal_error"
    status = 500


class ValidationError(ChronicleFlowError):
    code = "validation_error"
    status = 400


class NotFoundError(ChronicleFlowError):
    code = "not_found"
    status = 404


class ConflictError(ChronicleFlowError):
    code = "conflict"
    status = 409

from __future__ import annotations

from dataclasses import dataclass
from typing import Any

from .errors import ValidationError


def _identifier(value: Any, field: str) -> str:
    if not isinstance(value, str) or not value or len(value) > 100:
        raise ValidationError(f"{field} must be a non-empty string of at most 100 characters")
    return value


def _input_path(value: Any) -> str:
    if not isinstance(value, str) or not value or any(not segment for segment in value.split(".")):
        raise ValidationError("path must be a non-empty dot-separated input path")
    return value


def _json_scalar(value: Any, field: str) -> Any:
    if isinstance(value, (dict, list)):
        raise ValidationError(f"{field} must be a JSON scalar")
    return value


@dataclass(frozen=True)
class RunIf:
    condition_id: str
    expected: bool

    @classmethod
    def parse(cls, raw: Any) -> "RunIf":
        if not isinstance(raw, dict) or set(raw) != {"condition_id", "expected"}:
            raise ValidationError("run_if must contain exactly condition_id and expected")
        condition_id = _identifier(raw["condition_id"], "condition id")
        if not isinstance(raw["expected"], bool):
            raise ValidationError("run_if expected must be a boolean")
        return cls(condition_id, raw["expected"])

    def as_dict(self) -> dict[str, Any]:
        return {"condition_id": self.condition_id, "expected": self.expected}


@dataclass(frozen=True)
class Node:
    id: str
    kind: str
    depends_on: tuple[str, ...]
    path: str | None = None
    equals: Any = None
    run_if: RunIf | None = None
    body: tuple[str, ...] | None = None
    entry: str | None = None
    condition_id: str | None = None
    max_iterations: int | None = None

    @classmethod
    def parse(cls, raw: Any) -> "Node":
        if not isinstance(raw, dict):
            raise ValidationError("each node must be an object")
        kind = raw.get("kind")
        if kind not in ("task", "condition", "loop"):
            raise ValidationError("node kind must be task, condition, or loop")
        base = {"id", "kind", "depends_on"}
        if not base <= set(raw):
            raise ValidationError("each node must contain id, kind, and depends_on")
        node_id = _identifier(raw["id"], "node id")
        dependencies = raw["depends_on"]
        if not isinstance(dependencies, list) or any(not isinstance(item, str) for item in dependencies):
            raise ValidationError("depends_on must be an array of node identifiers")
        if len(dependencies) != len(set(dependencies)):
            raise ValidationError("depends_on must not contain duplicates")
        depends_on = tuple(dependencies)
        if kind == "task":
            if not set(raw) - base <= {"run_if"}:
                raise ValidationError("task nodes may only contain id, kind, depends_on, and run_if")
            run_if = RunIf.parse(raw["run_if"]) if "run_if" in raw else None
            return cls(node_id, "task", depends_on, run_if=run_if)
        if kind == "condition":
            if set(raw) != base | {"path", "equals"}:
                raise ValidationError("condition nodes must contain exactly id, kind, depends_on, path, and equals")
            return cls(
                node_id,
                "condition",
                depends_on,
                path=_input_path(raw["path"]),
                equals=_json_scalar(raw["equals"], "equals"),
            )
        if set(raw) != base | {"body", "entry", "condition_id", "max_iterations"}:
            raise ValidationError(
                "loop nodes must contain exactly id, kind, depends_on, body, entry, condition_id, and max_iterations"
            )
        body_raw = raw["body"]
        if not isinstance(body_raw, list) or not body_raw:
            raise ValidationError("loop body must be a non-empty array of node identifiers")
        if any(not isinstance(item, str) or not item for item in body_raw):
            raise ValidationError("loop body must be an array of node identifiers")
        if len(body_raw) != len(set(body_raw)):
            raise ValidationError("loop body must not contain duplicate node identifiers")
        entry = _identifier(raw["entry"], "loop entry")
        condition_id = _identifier(raw["condition_id"], "loop condition id")
        max_iterations = raw["max_iterations"]
        if not isinstance(max_iterations, int) or isinstance(max_iterations, bool) or not 1 <= max_iterations <= 1000:
            raise ValidationError("max_iterations must be an integer between 1 and 1000")
        return cls(
            node_id,
            "loop",
            depends_on,
            body=tuple(body_raw),
            entry=entry,
            condition_id=condition_id,
            max_iterations=max_iterations,
        )

    def as_dict(self) -> dict[str, Any]:
        document: dict[str, Any] = {"id": self.id, "kind": self.kind, "depends_on": list(self.depends_on)}
        if self.kind == "condition":
            document["path"] = self.path
            document["equals"] = self.equals
        elif self.kind == "loop":
            document["body"] = list(self.body)
            document["entry"] = self.entry
            document["condition_id"] = self.condition_id
            document["max_iterations"] = self.max_iterations
        elif self.run_if is not None:
            document["run_if"] = self.run_if.as_dict()
        return document


@dataclass(frozen=True)
class Workflow:
    id: str
    nodes: tuple[Node, ...]

    @classmethod
    def parse(cls, raw: Any) -> "Workflow":
        if not isinstance(raw, dict) or set(raw) != {"id", "nodes"}:
            raise ValidationError("workflow must contain exactly id and nodes")
        workflow_id = _identifier(raw["id"], "workflow id")
        if not isinstance(raw["nodes"], list) or not raw["nodes"]:
            raise ValidationError("nodes must be a non-empty array")
        nodes = tuple(Node.parse(node) for node in raw["nodes"])
        identifiers = {node.id for node in nodes}
        if len(identifiers) != len(nodes):
            raise ValidationError("node identifiers must be unique")
        by_id = {node.id: node for node in nodes}
        loops = [node for node in nodes if node.kind == "loop"]
        loop_owners: dict[str, str] = {}
        for loop in loops:
            for member_id in loop.body:
                if member_id in loop_owners:
                    raise ValidationError(
                        f"node {member_id} is listed in more than one loop body"
                    )
                loop_owners[member_id] = loop.id
        for node in nodes:
            owner = loop_owners.get(node.id)
            if node.id in node.depends_on:
                raise ValidationError(f"node {node.id} cannot depend on itself")
            missing = set(node.depends_on) - identifiers
            if missing:
                raise ValidationError(f"node {node.id} has unknown dependencies: {', '.join(sorted(missing))}")
            for dependency in node.depends_on:
                dependency_owner = loop_owners.get(dependency)
                if dependency_owner is not None and dependency_owner != owner:
                    if dependency_owner == node.id:
                        raise ValidationError(f"loop {node.id} cannot depend on one of its own body nodes")
                    raise ValidationError(
                        f"node {node.id} cannot depend on loop body node {dependency}; "
                        f"it is only available after loop {dependency_owner} completes"
                    )
            if node.kind == "loop":
                unknown_body = set(node.body) - identifiers
                if unknown_body:
                    raise ValidationError(
                        f"loop {node.id} body references unknown nodes: {', '.join(sorted(unknown_body))}"
                    )
                body_set = set(node.body)
                for member_id in node.body:
                    member = by_id[member_id]
                    if member.kind == "loop":
                        raise ValidationError(f"loop {node.id} body must not contain another loop")
                    if member.kind not in ("task", "condition"):
                        raise ValidationError(f"loop {node.id} body may only reference task and condition nodes")
                    out_of_body = set(member.depends_on) - body_set
                    if out_of_body:
                        raise ValidationError(
                            f"loop {node.id} body node {member_id} has out-of-body dependencies: "
                            f"{', '.join(sorted(out_of_body))}"
                        )
                if node.entry not in body_set:
                    raise ValidationError(f"loop {node.id} entry must be one of its body nodes")
                if node.condition_id not in body_set:
                    raise ValidationError(f"loop {node.id} condition_id must be one of its body nodes")
                if by_id[node.condition_id].kind != "condition":
                    raise ValidationError(f"loop {node.id} condition_id must reference a condition node")
        for node in nodes:
            if node.run_if is None:
                continue
            target = by_id.get(node.run_if.condition_id)
            if target is None or target.kind != "condition":
                raise ValidationError(f"node {node.id} run_if must reference a condition node")
            if node.run_if.condition_id not in node.depends_on:
                raise ValidationError(f"node {node.id} must list condition {node.run_if.condition_id} in depends_on")
            owner = loop_owners.get(node.id)
            if owner is not None and loop_owners.get(node.run_if.condition_id) != owner:
                raise ValidationError(
                    f"loop body node {node.id} run_if must reference a condition in the same loop body"
                )
        _assert_acyclic(by_id, nodes, loop_owners)
        return cls(workflow_id, nodes)

    def as_dict(self) -> dict[str, Any]:
        return {"id": self.id, "nodes": [node.as_dict() for node in self.nodes]}


def _assert_acyclic(
    by_id: dict[str, Node], nodes: tuple[Node, ...], loop_owners: dict[str, str]
) -> None:
    visiting: set[str] = set()
    visited: set[str] = set()

    def visit(node_id: str) -> None:
        if node_id in visiting:
            raise ValidationError("workflow contains a dependency cycle")
        if node_id in visited:
            return
        visiting.add(node_id)
        node = by_id[node_id]
        if node.kind == "loop":
            # A loop gates its body: successors reach body members through the
            # loop node, so only loop-level edges are traversed here.
            for dependency in node.depends_on:
                visit(dependency)
            _assert_body_acyclic(by_id, node)
        else:
            owner = loop_owners.get(node_id)
            for dependency in node.depends_on:
                if owner is None or loop_owners.get(dependency) == owner:
                    visit(dependency)
        visiting.remove(node_id)
        visited.add(node_id)

    for node in nodes:
        visit(node.id)


def _assert_body_acyclic(by_id: dict[str, Node], loop: Node) -> None:
    body_set = set(loop.body)
    visiting: set[str] = set()
    visited: set[str] = set()

    def visit(node_id: str) -> None:
        if node_id in visiting:
            raise ValidationError(f"loop {loop.id} body contains a dependency cycle")
        if node_id in visited:
            return
        visiting.add(node_id)
        for dependency in by_id[node_id].depends_on:
            if dependency in body_set:
                visit(dependency)
        visiting.remove(node_id)
        visited.add(node_id)

    for member_id in loop.body:
        visit(member_id)

from __future__ import annotations

from dataclasses import dataclass
from typing import Any

from .errors import ValidationError


def _identifier(value: Any, field: str) -> str:
    if not isinstance(value, str) or not value or len(value) > 100:
        raise ValidationError(f"{field} must be a non-empty string of at most 100 characters")
    return value


def _input_path(value: Any) -> str:
    if not isinstance(value, str) or not value or any(not segment for segment in value.split(".")):
        raise ValidationError("path must be a non-empty dot-separated input path")
    return value


def _json_scalar(value: Any, field: str) -> Any:
    if isinstance(value, (dict, list)):
        raise ValidationError(f"{field} must be a JSON scalar")
    return value


@dataclass(frozen=True)
class RunIf:
    condition_id: str
    expected: bool

    @classmethod
    def parse(cls, raw: Any) -> "RunIf":
        if not isinstance(raw, dict) or set(raw) != {"condition_id", "expected"}:
            raise ValidationError("run_if must contain exactly condition_id and expected")
        condition_id = _identifier(raw["condition_id"], "condition id")
        if not isinstance(raw["expected"], bool):
            raise ValidationError("run_if expected must be a boolean")
        return cls(condition_id, raw["expected"])

    def as_dict(self) -> dict[str, Any]:
        return {"condition_id": self.condition_id, "expected": self.expected}


@dataclass(frozen=True)
class Node:
    id: str
    kind: str
    depends_on: tuple[str, ...]
    path: str | None = None
    equals: Any = None
    run_if: RunIf | None = None
    loop_id: str | None = None
    body_entry: str | None = None
    condition_id: str | None = None
    max_iterations: int | None = None

    @classmethod
    def parse(cls, raw: Any) -> "Node":
        if not isinstance(raw, dict):
            raise ValidationError("each node must be an object")
        kind = raw.get("kind")
        if kind not in ("task", "condition", "loop"):
            raise ValidationError("node kind must be task, condition, or loop")
        base = {"id", "kind", "depends_on"}
        if not base <= set(raw):
            raise ValidationError("each node must contain id, kind, and depends_on")
        node_id = _identifier(raw["id"], "node id")
        dependencies = raw["depends_on"]
        if not isinstance(dependencies, list) or any(not isinstance(item, str) for item in dependencies):
            raise ValidationError("depends_on must be an array of node identifiers")
        if len(dependencies) != len(set(dependencies)):
            raise ValidationError("depends_on must not contain duplicates")
        depends_on = tuple(dependencies)
        if kind == "task":
            extra = set(raw) - base
            if not extra <= {"run_if", "loop_id"}:
                raise ValidationError("task nodes may only contain id, kind, depends_on, run_if, and loop_id")
            run_if = RunIf.parse(raw["run_if"]) if "run_if" in raw else None
            loop_id = _identifier(raw["loop_id"], "loop_id") if "loop_id" in raw else None
            return cls(node_id, "task", depends_on, run_if=run_if, loop_id=loop_id)
        if kind == "condition":
            if set(raw) != base | {"path", "equals"}:
                raise ValidationError("condition nodes must contain exactly id, kind, depends_on, path, and equals")
            return cls(
                node_id,
                "condition",
                depends_on,
                path=_input_path(raw["path"]),
                equals=_json_scalar(raw["equals"], "equals"),
            )
        # loop
        if set(raw) != base | {"body_entry", "condition_id", "max_iterations"}:
            raise ValidationError(
                "loop nodes must contain exactly id, kind, depends_on, body_entry, condition_id, and max_iterations"
            )
        body_entry = _identifier(raw["body_entry"], "body_entry")
        condition_id = _identifier(raw["condition_id"], "condition id")
        max_iterations = raw["max_iterations"]
        if not isinstance(max_iterations, int) or isinstance(max_iterations, bool) or not 1 <= max_iterations <= 1000:
            raise ValidationError("max_iterations must be an integer between 1 and 1000")
        return cls(
            node_id,
            "loop",
            depends_on,
            body_entry=body_entry,
            condition_id=condition_id,
            max_iterations=max_iterations,
        )

    def as_dict(self) -> dict[str, Any]:
        document: dict[str, Any] = {"id": self.id, "kind": self.kind, "depends_on": list(self.depends_on)}
        if self.kind == "condition":
            document["path"] = self.path
            document["equals"] = self.equals
        elif self.kind == "loop":
            document["body_entry"] = self.body_entry
            document["condition_id"] = self.condition_id
            document["max_iterations"] = self.max_iterations
        else:
            if self.run_if is not None:
                document["run_if"] = self.run_if.as_dict()
            if self.loop_id is not None:
                document["loop_id"] = self.loop_id
        return document


@dataclass(frozen=True)
class LoopSpec:
    node: Node
    members: frozenset[str]


@dataclass(frozen=True)
class Workflow:
    id: str
    nodes: tuple[Node, ...]
    loops: dict[str, LoopSpec]

    @classmethod
    def parse(cls, raw: Any) -> "Workflow":
        if not isinstance(raw, dict) or set(raw) != {"id", "nodes"}:
            raise ValidationError("workflow must contain exactly id and nodes")
        workflow_id = _identifier(raw["id"], "workflow id")
        if not isinstance(raw["nodes"], list) or not raw["nodes"]:
            raise ValidationError("nodes must be a non-empty array")
        nodes = tuple(Node.parse(node) for node in raw["nodes"])
        identifiers = {node.id for node in nodes}
        if len(identifiers) != len(nodes):
            raise ValidationError("node identifiers must be unique")
        by_id = {node.id: node for node in nodes}
        for node in nodes:
            if node.id in node.depends_on:
                raise ValidationError(f"node {node.id} cannot depend on itself")
            missing = set(node.depends_on) - identifiers
            if missing:
                raise ValidationError(f"node {node.id} has unknown dependencies: {', '.join(sorted(missing))}")
        for node in nodes:
            if node.run_if is None:
                continue
            target = by_id.get(node.run_if.condition_id)
            if target is None or target.kind != "condition":
                raise ValidationError(f"node {node.id} run_if must reference a condition node")
            if node.run_if.condition_id not in node.depends_on:
                raise ValidationError(f"node {node.id} must list condition {node.run_if.condition_id} in depends_on")
        loops = _build_loops(nodes, by_id)
        _assert_acyclic(nodes, by_id)
        return cls(workflow_id, nodes, loops)

    def as_dict(self) -> dict[str, Any]:
        return {"id": self.id, "nodes": [node.as_dict() for node in self.nodes]}

    @property
    def node_map(self) -> dict[str, Node]:
        return {node.id: node for node in self.nodes}


def _build_loops(nodes: tuple[Node, ...], by_id: dict[str, Node]) -> dict[str, LoopSpec]:
    loops: dict[str, LoopSpec] = {}
    for node in nodes:
        if node.kind != "loop":
            continue
        # condition_id must reference a condition that is a direct dependency of this loop
        target = by_id.get(node.condition_id)
        if target is None or target.kind != "condition":
            raise ValidationError(f"loop {node.id} condition_id must reference a condition node")
        if node.condition_id not in node.depends_on:
            raise ValidationError(f"loop {node.id} must list condition {node.condition_id} in depends_on")
        # body_entry must be a member of this loop
        entry = by_id.get(node.body_entry)
        if entry is None or entry.kind != "task" or entry.loop_id != node.id:
            raise ValidationError(f"loop {node.id} body_entry must be a task member of the loop")
        # body_entry must have no dependencies
        if entry.depends_on:
            raise ValidationError(f"loop {node.id} body_entry must have no dependencies")
        loops[node.id] = LoopSpec(node, frozenset())

    # every loop_id on a task must reference an existing loop; a task has at
    # most one loop_id field, so cross / duplicate ownership is impossible here
    for node in nodes:
        if node.kind == "task" and node.loop_id is not None and node.loop_id not in loops:
            raise ValidationError(f"task {node.id} references unknown loop {node.loop_id}")

    # a loop node never belongs to a loop body, and conditions cannot be members
    for node in nodes:
        if node.kind == "loop" and node.loop_id is not None:
            raise ValidationError(f"loop {node.id} cannot be a member of another loop")
        if node.kind == "condition" and node.loop_id is not None:
            raise ValidationError(f"condition {node.id} cannot be a loop member")

    # members may only depend on members of the same loop; loop nodes and
    # loop conditions may not be claimed as members of another loop
    for loop_id, spec in loops.items():
        members = {node.id for node in nodes if node.kind == "task" and node.loop_id == loop_id}
        for member_id in members:
            member = by_id[member_id]
            if member.run_if is not None:
                raise ValidationError(f"loop member {member_id} must not carry run_if")
            for dependency in member.depends_on:
                dep_node = by_id[dependency]
                if dep_node.kind != "task" or dep_node.loop_id != loop_id:
                    raise ValidationError(f"loop member {member_id} may only depend on members of loop {loop_id}")
        # every member must be reachable from body_entry through member edges:
        # a member is reachable when it (transitively) depends on the entry
        reachable: set[str] = set()
        stack = [spec.node.body_entry]
        while stack:
            current = stack.pop()
            if current in reachable:
                continue
            reachable.add(current)
            stack.extend(
                other.id
                for other in nodes
                if other.kind == "task" and other.loop_id == loop_id and current in other.depends_on
            )
        unreachable = members - reachable
        if unreachable:
            raise ValidationError(
                f"loop {loop_id} members must be reachable from body_entry: {', '.join(sorted(unreachable))}"
            )
        # the member dependency graph must remain acyclic on its own
        member_deps = {member_id: set(by_id[member_id].depends_on) for member_id in members}
        visiting: set[str] = set()
        visited: set[str] = set()

        def visit_member(member_id: str) -> None:
            if member_id in visiting:
                raise ValidationError(f"loop {loop_id} body contains a dependency cycle")
            if member_id in visited:
                return
            visiting.add(member_id)
            for dependency in member_deps[member_id]:
                visit_member(dependency)
            visiting.remove(member_id)
            visited.add(member_id)

        for member_id in members:
            visit_member(member_id)
        loops[loop_id] = LoopSpec(spec.node, frozenset(members))

    # nothing outside a loop may depend into its body; the loop node owns completion
    for node in nodes:
        for dependency in node.depends_on:
            dep_node = by_id[dependency]
            if dep_node.kind == "task" and dep_node.loop_id is not None:
                owner = dep_node.loop_id
                if node.kind == "task" and node.loop_id == owner:
                    continue
                if node.id == owner:
                    raise ValidationError(f"loop {owner} must not depend directly on its body members")
                raise ValidationError(f"node {node.id} must depend on loop {owner} instead of its members")

    return loops


def _assert_acyclic(nodes: tuple[Node, ...], by_id: dict[str, Node]) -> None:
    # Contract loop bodies: members are skipped here (their internal graph is
    # validated separately in _build_loops) and nothing outside a body may
    # depend on a member, so member ids never appear as edges of other nodes.
    graph: dict[str, set[str]] = {}
    for node in nodes:
        if node.kind == "task" and node.loop_id is not None:
            continue
        edges = {dep for dep in node.depends_on if not (by_id[dep].kind == "task" and by_id[dep].loop_id is not None)}
        graph[node.id] = edges

    visiting: set[str] = set()
    visited: set[str] = set()

    def visit(node_id: str) -> None:
        if node_id in visiting:
            raise ValidationError("workflow contains a dependency cycle")
        if node_id in visited:
            return
        visiting.add(node_id)
        for dependency in graph.get(node_id, ()):  # type: ignore[union-attr]
            visit(dependency)
        visiting.remove(node_id)
        visited.add(node_id)

    for node_id in graph:
        visit(node_id)

from __future__ import annotations

from typing import Any, Callable

from .errors import ConflictError, NotFoundError, ValidationError
from .model import Node, Workflow, _identifier
from .store import Store


def _json_type(value: Any) -> str:
    if value is None:
        return "null"
    if isinstance(value, bool):
        return "boolean"
    if isinstance(value, (int, float)):
        return "number"
    if isinstance(value, str):
        return "string"
    return "other"


def _evaluate_condition(node: Node, input_data: Any) -> bool:
    current = input_data
    for segment in node.path.split("."):
        if not isinstance(current, dict) or segment not in current:
            return False
        current = current[segment]
    return _json_type(current) == _json_type(node.equals) and current == node.equals


class ChronicleFlow:
    def __init__(self, database: str):
        self.store = Store(database)

    def _idempotent(self, key: str | None, operation: str, action: Callable[[], dict[str, Any]]) -> dict[str, Any]:
        if not key:
            raise ValidationError("Idempotency-Key header is required")
        with self.store.transaction() as connection:
            existing = connection.execute("SELECT operation, response FROM idempotency WHERE key = ?", (key,)).fetchone()
            if existing:
                if existing["operation"] != operation:
                    raise ConflictError("idempotency key was already used for another operation")
                return self.store.decode(existing["response"])
            response = action()
            connection.execute(
                "INSERT INTO idempotency(key, operation, response) VALUES (?, ?, ?)",
                (key, operation, self.store.encode(response)),
            )
            return response

    def create_workflow(self, raw: Any, key: str | None) -> dict[str, Any]:
        workflow = Workflow.parse(raw)

        def create() -> dict[str, Any]:
            try:
                self.store.connection.execute(
                    "INSERT INTO workflows(id, document) VALUES (?, ?)",
                    (workflow.id, self.store.encode(workflow.as_dict())),
                )
            except Exception as error:
                if "UNIQUE constraint" in str(error):
                    raise ConflictError(f"workflow {workflow.id} already exists") from error
                raise
            return workflow.as_dict()

        return self._idempotent(key, f"create-workflow:{workflow.id}", create)

    def create_execution(self, raw: Any, key: str | None) -> dict[str, Any]:
        if not isinstance(raw, dict) or set(raw) != {"id", "workflow_id", "input"}:
            raise ValidationError("execution must contain exactly id, workflow_id, and input")
        execution_id = _identifier(raw["id"], "execution id")
        workflow_id = _identifier(raw["workflow_id"], "workflow id")
        if not isinstance(raw["input"], dict):
            raise ValidationError("input must be an object")

        def create() -> dict[str, Any]:
            workflow_row = self.store.connection.execute("SELECT document FROM workflows WHERE id = ?", (workflow_id,)).fetchone()
            if not workflow_row:
                raise NotFoundError(f"workflow {workflow_id} was not found")
            workflow = Workflow.parse(self.store.decode(workflow_row["document"]))
            state = self._initial_state(execution_id, workflow_id, raw["input"], workflow)
            try:
                self.store.connection.execute(
                    "INSERT INTO executions(id, workflow_id, state) VALUES (?, ?, ?)",
                    (execution_id, workflow_id, self.store.encode(state)),
                )
            except Exception as error:
                if "UNIQUE constraint" in str(error):
                    raise ConflictError(f"execution {execution_id} already exists") from error
                raise
            self._append(
                execution_id,
                "execution_started",
                {
                    "workflow_id": workflow_id,
                    "input": raw["input"],
                    "loops": [loop.id for loop in workflow.nodes if loop.kind == "loop"],
                },
            )
            return state

        return self._idempotent(key, f"create-execution:{execution_id}", create)

    @staticmethod
    def _initial_state(execution_id: str, workflow_id: str, input_data: dict[str, Any], workflow: Workflow) -> dict[str, Any]:
        return {
            "id": execution_id,
            "workflow_id": workflow_id,
            "status": "running",
            "input": input_data,
            "completed_nodes": [],
            "skipped_nodes": [],
            "condition_results": {},
            "outputs": {},
            "loops": {
                loop.id: {
                    "status": "waiting",
                    "current_iteration": 0,
                    "reason": None,
                    "iterations": [],
                }
                for loop in workflow.nodes
                if loop.kind == "loop"
            },
        }

    def get_execution(self, execution_id: str) -> dict[str, Any]:
        row = self.store.connection.execute("SELECT state FROM executions WHERE id = ?", (execution_id,)).fetchone()
        if not row:
            raise NotFoundError(f"execution {execution_id} was not found")
        return self.store.decode(row["state"])

    def events(self, execution_id: str) -> list[dict[str, Any]]:
        self.get_execution(execution_id)
        rows = self.store.connection.execute(
            "SELECT sequence, type, payload, occurred_at FROM events WHERE execution_id = ? ORDER BY sequence",
            (execution_id,),
        ).fetchall()
        return [
            {"sequence": row["sequence"], "type": row["type"], "payload": self.store.decode(row["payload"]), "occurred_at": row["occurred_at"]}
            for row in rows
        ]

    def advance(self, execution_id: str, raw: Any, key: str | None) -> dict[str, Any]:
        if not isinstance(raw, dict) or set(raw) != {"output"} or not isinstance(raw["output"], dict):
            raise ValidationError("advance body must contain exactly an output object")

        def apply() -> dict[str, Any]:
            state = self.get_execution(execution_id)
            if state["status"] != "running":
                return state
            workflow_row = self.store.connection.execute("SELECT document FROM workflows WHERE id = ?", (state["workflow_id"],)).fetchone()
            workflow = Workflow.parse(self.store.decode(workflow_row["document"]))
            engine = _Engine(self, execution_id, workflow, state)
            engine.auto_process()
            if state["status"] == "running":
                ready = engine.ready_tasks()
                if not ready:
                    raise ConflictError("execution has no ready node")
                node_id, iteration = ready[0]
                engine.complete_task(node_id, iteration, raw["output"])
                engine.auto_process()
            self.store.connection.execute("UPDATE executions SET state = ? WHERE id = ?", (self.store.encode(state), execution_id))
            return state

        return self._idempotent(key, f"advance:{execution_id}", apply)

    def replay(self, execution_id: str) -> dict[str, Any]:
        stored = self.get_execution(execution_id)
        rebuilt: dict[str, Any] | None = None
        loops_state: dict[str, Any] = {}

        def iteration_record(loop_id: str, iteration: int) -> dict[str, Any]:
            record = loops_state[loop_id]
            while len(record["iterations"]) < iteration:
                record["iterations"].append(
                    {
                        "iteration": len(record["iterations"]) + 1,
                        "completed_nodes": [],
                        "skipped_nodes": [],
                        "condition_results": {},
                    }
                )
            return record["iterations"][iteration - 1]

        for event in self.events(execution_id):
            payload = event["payload"]
            if event["type"] == "execution_started":
                loops_state = {
                    loop_id: {"status": "waiting", "current_iteration": 0, "reason": None, "iterations": []}
                    for loop_id in payload.get("loops", [])
                }
                rebuilt = {
                    "id": execution_id,
                    "workflow_id": payload["workflow_id"],
                    "status": "running",
                    "input": payload["input"],
                    "completed_nodes": [],
                    "skipped_nodes": [],
                    "condition_results": {},
                    "outputs": {},
                    "loops": loops_state,
                }
                continue
            if rebuilt is None:
                continue
            if event["type"] == "condition_evaluated":
                node_id = payload["node_id"]
                if "loop_id" in payload:
                    entry = iteration_record(payload["loop_id"], payload["iteration"])
                    entry["condition_results"][node_id] = payload["result"]
                    entry["completed_nodes"].append(node_id)
                    rebuilt["condition_results"].setdefault(node_id, []).append(payload["result"])
                else:
                    rebuilt["condition_results"][node_id] = payload["result"]
                    rebuilt["completed_nodes"].append(node_id)
            elif event["type"] == "node_skipped":
                if "loop_id" in payload:
                    iteration_record(payload["loop_id"], payload["iteration"])["skipped_nodes"].append(payload["node_id"])
                else:
                    rebuilt["skipped_nodes"].append(payload["node_id"])
            elif event["type"] == "node_completed":
                if "loop_id" in payload:
                    entry = iteration_record(payload["loop_id"], payload["iteration"])
                    entry["completed_nodes"].append(payload["node_id"])
                    rebuilt["outputs"].setdefault(payload["node_id"], []).append(payload["output"])
                else:
                    rebuilt["completed_nodes"].append(payload["node_id"])
                    rebuilt["outputs"][payload["node_id"]] = payload["output"]
            elif event["type"] == "loop_started":
                loops_state[payload["loop_id"]]["status"] = "running"
            elif event["type"] == "iteration_started":
                record = loops_state[payload["loop_id"]]
                record["current_iteration"] = payload["iteration"]
                iteration_record(payload["loop_id"], payload["iteration"])
            elif event["type"] == "loop_completed":
                record = loops_state[payload["loop_id"]]
                record["status"] = "completed"
                record["reason"] = payload["reason"]
                record["current_iteration"] = len(record["iterations"])
                rebuilt["completed_nodes"].append(payload["loop_id"])
            elif event["type"] == "execution_completed":
                rebuilt["status"] = "completed"
        if rebuilt is None:
            raise ConflictError("execution event stream has no start event")
        return {"consistent": rebuilt == stored, "execution": rebuilt}

    def _append(self, execution_id: str, event_type: str, payload: dict[str, Any]) -> None:
        row = self.store.connection.execute(
            "SELECT COALESCE(MAX(sequence), 0) + 1 AS sequence FROM events WHERE execution_id = ?",
            (execution_id,),
        ).fetchone()
        self.store.connection.execute(
            "INSERT INTO events(execution_id, sequence, type, payload, occurred_at) VALUES (?, ?, ?, ?, ?)",
            (execution_id, row["sequence"], event_type, self.store.encode(payload), self.store.now()),
        )


class _Engine:
    """Materializes workflow state transitions and records them as events.

    Loop event protocol (all payloads carry loop_id):

    - loop_started {} then loop_condition_evaluated {phase:"entry",result}
    - on a true judgment: iteration_started {iteration}
    - body node events carry iteration; iteration_completed {iteration}
    - loop_condition_evaluated {phase:"between",iteration,result}
    - loop_completed {reason,iterations} where reason is condition_false
      or iteration_limit
    """

    def __init__(self, service: ChronicleFlow, execution_id: str, workflow: Workflow, state: dict[str, Any]):
        self.service = service
        self.execution_id = execution_id
        self.workflow = workflow
        self.state = state
        self.by_id = {node.id: node for node in workflow.nodes}
        self.loops = sorted((node for node in workflow.nodes if node.kind == "loop"), key=lambda node: node.id)
        self.loop_owners = {
            member_id: loop.id for loop in self.loops for member_id in loop.body
        }

    def append(self, event_type: str, payload: dict[str, Any]) -> None:
        self.service._append(self.execution_id, event_type, payload)

    def loop_record(self, loop_id: str) -> dict[str, Any]:
        return self.state["loops"][loop_id]

    def iteration_entry(self, loop_id: str, iteration: int) -> dict[str, Any]:
        return self.loop_record(loop_id)["iterations"][iteration - 1]

    def is_finished(self, node_id: str, iteration: int | None = None) -> bool:
        owner = self.loop_owners.get(node_id)
        if owner is None:
            return node_id in self.state["completed_nodes"] or node_id in self.state["skipped_nodes"]
        record = self.loop_record(owner)
        if record["status"] != "running" or record["current_iteration"] != iteration:
            return False
        entry = record["iterations"][iteration - 1]
        return node_id in entry["completed_nodes"] or node_id in entry["skipped_nodes"]

    def dependencies_satisfied(self, node: Node, iteration: int | None) -> bool:
        for dependency_id in node.depends_on:
            if self.loop_owners.get(dependency_id) == self.loop_owners.get(node.id):
                if not self.is_finished(dependency_id, iteration):
                    return False
            elif dependency_id not in self.state["completed_nodes"] and dependency_id not in self.state["skipped_nodes"]:
                return False
        return True

    def condition_value(self, condition_id: str, iteration: int | None) -> bool:
        results = self.state["condition_results"][condition_id]
        return results if iteration is None else results[iteration - 1]

    # -- outer DAG --------------------------------------------------------

    def evaluate_outer_condition(self, node: Node) -> bool:
        if self.is_finished(node.id) or not self.dependencies_satisfied(node, None):
            return False
        result = _evaluate_condition(node, self.state["input"])
        self.state["condition_results"][node.id] = result
        self.state["completed_nodes"].append(node.id)
        self.append("condition_evaluated", {"node_id": node.id, "result": result})
        return True

    def skip_outer_task_if_guarded(self, node: Node) -> bool:
        if node.run_if is None or self.is_finished(node.id) or not self.dependencies_satisfied(node, None):
            return False
        if self.condition_value(node.run_if.condition_id, None) == node.run_if.expected:
            return False
        self.state["skipped_nodes"].append(node.id)
        self.append("node_skipped", {"node_id": node.id})
        return True

    # -- loops ------------------------------------------------------------

    def ready_loops(self) -> list[Node]:
        settled = set(self.state["completed_nodes"]) | set(self.state["skipped_nodes"])
        return [
            loop
            for loop in self.loops
            if self.loop_record(loop.id)["status"] == "waiting" and set(loop.depends_on) <= settled
        ]

    def start_loop(self, loop: Node) -> None:
        record = self.loop_record(loop.id)
        record["status"] = "running"
        self.append("loop_started", {"loop_id": loop.id})
        result = _evaluate_condition(self.by_id[loop.condition_id], self.state["input"])
        self.append(
            "loop_condition_evaluated",
            {"loop_id": loop.id, "condition_id": loop.condition_id, "phase": "entry", "result": result},
        )
        if result is False:
            self.finish_loop(loop, "condition_false")
        else:
            self.start_iteration(loop, 1)

    def start_iteration(self, loop: Node, iteration: int) -> None:
        record = self.loop_record(loop.id)
        record["current_iteration"] = iteration
        record["iterations"].append(
            {"iteration": iteration, "completed_nodes": [], "skipped_nodes": [], "condition_results": {}}
        )
        self.append("iteration_started", {"loop_id": loop.id, "iteration": iteration})

    def finish_loop(self, loop: Node, reason: str) -> None:
        record = self.loop_record(loop.id)
        record["status"] = "completed"
        record["reason"] = reason
        record["current_iteration"] = len(record["iterations"])
        self.state["completed_nodes"].append(loop.id)
        self.append(
            "loop_completed",
            {"loop_id": loop.id, "reason": reason, "iterations": len(record["iterations"])},
        )

    def evaluate_body_condition(self, loop: Node, iteration: int, node: Node) -> bool:
        if self.is_finished(node.id, iteration) or not self.dependencies_satisfied(node, iteration):
            return False
        result = _evaluate_condition(node, self.state["input"])
        entry = self.iteration_entry(loop.id, iteration)
        entry["condition_results"][node.id] = result
        self.state["condition_results"].setdefault(node.id, []).append(result)
        entry["completed_nodes"].append(node.id)
        self.append(
            "condition_evaluated",
            {"loop_id": loop.id, "iteration": iteration, "node_id": node.id, "result": result},
        )
        return True

    def skip_body_task_if_guarded(self, loop: Node, iteration: int, node: Node) -> bool:
        if node.run_if is None or self.is_finished(node.id, iteration) or not self.dependencies_satisfied(node, iteration):
            return False
        if self.condition_value(node.run_if.condition_id, iteration) == node.run_if.expected:
            return False
        self.iteration_entry(loop.id, iteration)["skipped_nodes"].append(node.id)
        self.append(
            "node_skipped",
            {"loop_id": loop.id, "iteration": iteration, "node_id": node.id},
        )
        return True

    def complete_task(self, node_id: str, iteration: int | None, output: dict[str, Any]) -> None:
        if iteration is None:
            self.state["completed_nodes"].append(node_id)
            self.state["outputs"][node_id] = output
            self.append("node_completed", {"node_id": node_id, "output": output})
            return
        owner = self.loop_owners[node_id]
        self.iteration_entry(owner, iteration)["completed_nodes"].append(node_id)
        self.state["outputs"].setdefault(node_id, []).append(output)
        self.append(
            "node_completed",
            {"loop_id": owner, "iteration": iteration, "node_id": node_id, "output": output},
        )

    def settle_iteration(self, loop: Node, iteration: int) -> bool:
        """Auto-evaluate conditions and skip guarded tasks inside one round."""
        progressed = False
        changed = True
        while changed:
            changed = False
            for member_id in sorted(loop.body):
                node = self.by_id[member_id]
                if self.is_finished(member_id, iteration):
                    continue
                if node.kind == "condition":
                    if self.evaluate_body_condition(loop, iteration, node):
                        changed = True
                        progressed = True
                elif self.skip_body_task_if_guarded(loop, iteration, node):
                    changed = True
                    progressed = True
        return progressed

    def close_iteration_if_done(self, loop: Node) -> bool:
        """Finish a round whose whole body is settled. Returns progress flag."""
        record = self.loop_record(loop.id)
        if record["status"] != "running":
            return False
        iteration = record["current_iteration"]
        entry = record["iterations"][iteration - 1]
        done = set(entry["completed_nodes"]) | set(entry["skipped_nodes"])
        if not set(loop.body) <= done:
            return False
        self.append("iteration_completed", {"loop_id": loop.id, "iteration": iteration})
        # The control condition is a body node, so it was auto-evaluated while
        # the round was settled; the round-end judgment reuses that result.
        result = entry["condition_results"][loop.condition_id]
        self.append(
            "loop_condition_evaluated",
            {
                "loop_id": loop.id,
                "condition_id": loop.condition_id,
                "phase": "between",
                "iteration": iteration,
                "result": result,
            },
        )
        if result is False:
            self.finish_loop(loop, "condition_false")
        elif iteration >= loop.max_iterations:
            self.finish_loop(loop, "iteration_limit")
        else:
            self.start_iteration(loop, iteration + 1)
        return True

    # -- main fixed point -------------------------------------------------

    def auto_process(self) -> None:
        outer_conditions = sorted(
            (node for node in self.workflow.nodes if node.kind == "condition" and node.id not in self.loop_owners),
            key=lambda node: node.id,
        )
        outer_tasks = sorted(
            (node for node in self.workflow.nodes if node.kind == "task" and node.id not in self.loop_owners),
            key=lambda node: node.id,
        )
        progressed = True
        while progressed:
            progressed = False
            for loop in self.ready_loops():
                self.start_loop(loop)
                progressed = True
            for loop in self.loops:
                record = self.loop_record(loop.id)
                if record["status"] != "running":
                    continue
                iteration = record["current_iteration"]
                if self.settle_iteration(loop, iteration):
                    progressed = True
                if self.close_iteration_if_done(loop):
                    progressed = True
            for node in outer_conditions:
                if self.evaluate_outer_condition(node):
                    progressed = True
            for node in outer_tasks:
                if self.skip_outer_task_if_guarded(node):
                    progressed = True
        # Body nodes are encapsulated by their loop: they only appear in the
        # per-iteration records, never in the top-level lists.
        total = len(self.workflow.nodes) - len(self.loop_owners)
        if len(self.state["completed_nodes"]) + len(self.state["skipped_nodes"]) == total:
            if self.state["status"] == "running":
                self.state["status"] = "completed"
                self.append("execution_completed", {})

    def ready_tasks(self) -> list[tuple[str, int | None]]:
        """All ready tasks, lexicographically smallest node id first."""
        ready: list[tuple[str, int | None]] = []
        for loop in self.loops:
            record = self.loop_record(loop.id)
            if record["status"] != "running":
                continue
            iteration = record["current_iteration"]
            for member_id in loop.body:
                node = self.by_id[member_id]
                if (
                    node.kind == "task"
                    and not self.is_finished(member_id, iteration)
                    and self.dependencies_satisfied(node, iteration)
                ):
                    ready.append((member_id, iteration))
        for node in self.workflow.nodes:
            if node.kind == "task" and node.id not in self.loop_owners:
                if not self.is_finished(node.id) and self.dependencies_satisfied(node, None):
                    ready.append((node.id, None))
        ready.sort(key=lambda item: item[0])
        return ready

