def _reaches(source_id: str, target_id: str, by_id: dict[str, Node], scope: set[str]) -> bool:
    """Whether source_id transitively depends on target_id inside scope."""
    seen: set[str] = set()
    stack = list(by_id[source_id].depends_on)
    while stack:
        current = stack.pop()
        if current == target_id:
            return True
        if current in seen or current not in scope:
            continue
        seen.add(current)
        stack.extend(by_id[current].depends_on)
    return False

